CREATE TABLE IF NOT EXISTS cms_apps(id BIGSERIAL PRIMARY KEY,site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,app_key VARCHAR(190) NOT NULL,label TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','archived')),navigation_json TEXT NOT NULL DEFAULT '[]',settings_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(site_id,app_key));
CREATE TABLE IF NOT EXISTS cms_app_entities(id BIGSERIAL PRIMARY KEY,app_id BIGINT NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,entity_key VARCHAR(190) NOT NULL,label TEXT NOT NULL,plural_label TEXT NOT NULL,storage_type VARCHAR(20) NOT NULL DEFAULT 'content' CHECK(storage_type IN('content','custom')),content_type_key VARCHAR(190),form_key VARCHAR(190),workflow_key VARCHAR(190),permissions_json TEXT NOT NULL DEFAULT '{}',settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(app_id,entity_key));
CREATE TABLE IF NOT EXISTS cms_app_relations(id BIGSERIAL PRIMARY KEY,app_id BIGINT NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,relation_key VARCHAR(190) NOT NULL,source_entity_key VARCHAR(190) NOT NULL,target_entity_key VARCHAR(190) NOT NULL,relation_type VARCHAR(20) NOT NULL CHECK(relation_type IN('one_to_one','one_to_many','many_to_many')),settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(app_id,relation_key));
CREATE TABLE IF NOT EXISTS cms_app_views(id BIGSERIAL PRIMARY KEY,app_id BIGINT NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,view_key VARCHAR(190) NOT NULL,entity_key VARCHAR(190) NOT NULL,view_type VARCHAR(20) NOT NULL CHECK(view_type IN('list','detail','form','dashboard')),columns_json TEXT NOT NULL DEFAULT '[]',filters_json TEXT NOT NULL DEFAULT '[]',sort_json TEXT NOT NULL DEFAULT '[]',settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(app_id,view_key));
CREATE TABLE IF NOT EXISTS cms_app_routes(id BIGSERIAL PRIMARY KEY,app_id BIGINT NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,route_key VARCHAR(190) NOT NULL,path VARCHAR(500) NOT NULL,view_key VARCHAR(190) NOT NULL,permission_key VARCHAR(190) NOT NULL DEFAULT '',UNIQUE(app_id,route_key),UNIQUE(app_id,path));
CREATE TABLE IF NOT EXISTS cms_app_blueprints(id BIGSERIAL PRIMARY KEY,blueprint_key VARCHAR(190) NOT NULL UNIQUE,label TEXT NOT NULL,definition_json TEXT NOT NULL,version VARCHAR(64) NOT NULL DEFAULT '1.0.0',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
